import math

def calc_score(U):
    """Calculate the score for a set U."""
    if not U:
        return 0
    U = list(set(U))
    if 0 not in U:
        return 0
    max_u = max(U)
    if max_u == 0:
        return 0

    sums = set()
    diffs = set()
    for a in U:
        for b in U:
            sums.add(a + b)
            diffs.add(a - b)

    num = len(diffs) / len(sums)
    den = math.log(2 * max_u + 1)
    if den == 0:
        return 0
    return 1 + math.log(num) / den

def evaluate_set_fast(B, n):
    """Calculate score for full base-B binary digit set {0,1}^n assuming no carries (B>=3)."""
    if B < 3:
        return 0
    num = (5.0 / 3.0) ** n
    max_u = (B ** n - 1) / (B - 1)
    den = math.log(2 * max_u + 1)
    if den == 0:
        return 0
    return 1 + math.log(num) / den

